// ─────────────────────────────────────────────────────────────────────────────
// Pri Learning · the committed certification report describes the content
// that is actually in the tree
//
// docs/content/certification-report.{md,json} is regenerated by
// `npm run content:certify` (the full run). It went stale once already: the
// report said 2026.10.0 while main served 2026.10.5, and Login.jsx cited it
// as launch certification (audit item 12). This gate fails CI whenever the
// report is older than the content it describes:
//
//   · its content version is not CONTENT_VERSION;
//   · any V1 generator's seeded output differs from the committed digest, or
//     a V1 generator has no digest at all (the digest is refreshed by
//     `npm run content:digest`, which is only legal once CONTENT_VERSION moved);
//   · it certifies a different number of paths, advertised paths or exam
//     selections than the tree now enumerates;
//   · it was written in fast mode, or with a different past-papers default;
//   · it records any failing path, cell, backend request or exam selection.
//
// It does not rerun the certifier (that is `test:content:cert`); it checks
// that the artefact a reader would trust is the artefact this tree produces.
// ─────────────────────────────────────────────────────────────────────────────
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

let pass = 0;
const failures = [];
const ok = (cond, label) => { if (cond) pass++; else failures.push(label); };
const eq = (actual, expected, label) => ok(actual === expected, `${label} — expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);

const { CONTENT_VERSION } = await import('../src/engine/contentIdentity.js');
const { pastPapersEnabled } = await import('../src/engine/pastPapers.js');
const { loadAllBanks } = await import('../src/engine/generators/index.js');
const { enumeratePaths, loadBanksForPaths, generatorDigests, compareDigests, coverGenerators, V1_EXAMS } = await import('./content-certify.mjs');

const mdPath = join(ROOT, 'docs/content/certification-report.md');
const jsonPath = join(ROOT, 'docs/content/certification-report.json');
const digestPath = join(ROOT, 'docs/content/content-digest.json');
ok(existsSync(mdPath) && existsSync(jsonPath) && existsSync(digestPath), 'the report, its JSON and the content digest are committed');
if (failures.length) { console.log(`CONTENT REPORT FRESH: FAIL — ${failures.join('; ')}`); process.exit(1); }

const md = readFileSync(mdPath, 'utf8');
const report = JSON.parse(readFileSync(jsonPath, 'utf8'));
const digest = JSON.parse(readFileSync(digestPath, 'utf8'));
const s = report.summary || {};

// ── Version ─────────────────────────────────────────────────────────────────
eq(s.contentVersion, CONTENT_VERSION, 'the JSON report carries the current CONTENT_VERSION');
ok(md.includes(`- Content version: \`${CONTENT_VERSION}\``), `the Markdown report states the current CONTENT_VERSION ${CONTENT_VERSION}`);
eq(digest.contentVersion, CONTENT_VERSION, 'the content digest carries the current CONTENT_VERSION');
ok(/DIFFICULTY_UNAVAILABLE/.test(md), 'the report describes refusal of a named level (DIFFICULTY_UNAVAILABLE), not silent snapping');

// ── Generator digests: the tree's output is the committed output ────────────
await loadAllBanks();
const paths = enumeratePaths();
await loadBanksForPaths(paths);
// The same set the certifier digests: every generator a V1 chapter declares,
// plus (when past papers are on) the archive generators it served.
const v1 = coverGenerators();
const cmp = compareDigests(digest, generatorDigests(v1), CONTENT_VERSION);
eq(cmp.changed.length, 0, `no V1 generator's seeded output differs from the committed digest (${cmp.changed.slice(0, 8).join(', ')})`);
// A digested generator that this tree no longer declares is tolerated only
// when it is an archive generator and past papers are off (it was served when
// the digest was written with the switch on); anything else has disappeared.
const vanished = cmp.removed.filter(id => pastPapersEnabled() || !/^(pyq-|jee-main-|jee-advanced-)/.test(id));
eq(vanished.length, 0, `no digested generator has disappeared (${vanished.slice(0, 8).join(', ')})`);
eq(cmp.added.length, 0, `every V1 generator has a committed digest (${cmp.added.slice(0, 8).join(', ')}) — run npm run content:digest`);

// ── Scope: the report covers what the tree enumerates ───────────────────────
eq(s.mode, 'full', 'the committed report is a full run');
eq(s.paths, paths.length, 'the report certifies every enumerated launch path');
eq(s.advertisedPaths, paths.filter(p => p.advertised).length, 'the report\'s advertised-path count matches the tree');
eq(s.exams?.selections, V1_EXAMS.length, 'the report covers every V1 exam selection');
eq(s.pastPapers?.enabled, pastPapersEnabled(), 'the report was written with the same past-papers default the tree has');
eq(s.pastPapers?.paths, paths.filter(p => p.pyqOnly).length, 'the report counts the same archive paths');
ok(md.includes(`- Paths: **${s.paths}/${s.paths} pass** (${s.advertisedPaths} advertised)`), 'the Markdown path line agrees with the JSON');

// ── Result: nothing in it failed ────────────────────────────────────────────
eq(s.failed, 0, 'no launch path failed');
eq(s.questionsFailed, 0, 'no served question failed');
eq(s.emptyAdvertisedPaths, 0, 'no advertised path served nothing');
eq(s.difficultyMismatch, 0, 'no question was served at a rung other than the one resolved');
eq(s.repeatsAvoidable, 0, 'no avoidable repeat');
eq(s.exams?.failed, 0, 'no exam item failed');
eq(s.exams?.passed, s.exams?.selections, 'every exam selection passed');
ok(s.exams?.papers === s.exams?.selections * s.examSeeds, `every exam selection issued its ${s.examSeeds} papers (${s.exams?.papers})`);
eq(s.backend?.passed, s.backend?.paths, 'every end-to-end request was answered as declared');
eq(s.generatorCells?.passed, s.generatorCells?.cells, 'every generator cell passed');
ok(Array.isArray(report.generatorCellFailures) && report.generatorCellFailures.length === 0, 'no generator-cell failure is recorded');
ok(Array.isArray(report.backendFailures) && report.backendFailures.length === 0, 'no backend failure is recorded');
ok(md.includes('## Failing paths\n\nNone.'), 'the Markdown report lists no failing path');

const total = pass + failures.length;
if (failures.length) {
  for (const f of failures) console.log(`FAIL ${f}`);
  console.log(`CONTENT REPORT FRESH: FAIL — ${pass}/${total} checks — regenerate with npm run content:certify (and npm run content:digest after a CONTENT_VERSION bump)`);
  process.exit(1);
}
console.log(`CONTENT REPORT FRESH: PASS — ${pass}/${total} checks — docs/content/certification-report.md describes contentVersion ${CONTENT_VERSION}, ${s.paths} paths, ${s.exams.selections} exam selections, digest current`);
